namespace Djohnnie.SoftwareFactory.DataAccess.Sql.Entities;

/// <summary>The keys every table has; <see cref="Configuration.EntityKeysConfiguration"/> maps them.</summary>
public abstract class Entity
{
    /// <summary>The primary key, generated by the application. Foreign keys and everything outside the database use it.</summary>
    public Guid Id { get; set; }

    /// <summary>An incrementing number generated by the database; the clustered index, so rows are stored in insertion order.</summary>
    public int SysId { get; set; }
}
